    "count-array-element-markdown-code-2": "#include <cuda_runtime.h>\n\n// input, output are device pointers\nextern \"C\" void solve(const int* input, int* output, int N, int K) {}",
    "count-array-element-markdown-code-3": "#include <cuda_runtime.h>\n\n__global__ void count_kernel(const int* input, int* output, int N, int K) {\n    __shared__ int counts[256];\n    int tid = threadIdx.x;\n    int index = blockIdx.x * blockDim.x + tid;\n    int stride = blockDim.x * gridDim.x;\n    int local = 0;\n\n    for (int i = index; i < N; i += stride) {\n        local += input[i] == K;\n    }\n    counts[tid] = local;\n    __syncthreads();\n\n    for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {\n        if (tid < offset) counts[tid] += counts[tid + offset];\n        __syncthreads();\n    }\n    if (tid == 0) atomicAdd(output, counts[0]);\n}\n\n// input, output are device pointers\nextern \"C\" void solve(const int* input, int* output, int N, int K) {\n    cudaMemset(output, 0, sizeof(int));\n    int threads = 256;\n    int blocks = (N + threads - 1) / threads;\n    if (blocks > 1024) blocks = 1024;\n    count_kernel<<<blocks, threads>>>(input, output, N, K);\n    cudaDeviceSynchronize();\n}"
